SELECT COUNT(*) AS n_rows,
       COUNT(amount) AS n_amount
FROM orders;

SELECT PERCENTILE_CONT(ARRAY[0.25, 0.5, 0.75])
       WITHIN GROUP (ORDER BY amount) AS quartiles
FROM orders;

SELECT STDDEV_SAMP(amount) AS sd,
       VAR_SAMP(amount) AS variance
FROM orders;

SELECT * FROM orders TABLESAMPLE BERNOULLI (10);

SELECT * FROM orders
ORDER BY RANDOM()
LIMIT 500;
